quests[11622] = { id = 11622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Riplash", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests.  Perhaps she can tell you more about what the writing on the tablet means.", sourceObjective = "Find Veehja at the ruins of Riplash in Borean Tundra.There is someone who might shed light on this mystery, {race}. It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests. Perhaps she can tell you more about what the writing on the tablet means.", sourceObjectiveStatus = "unverified-source-field" }
quests[11623] = { id = 11623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit to the Curator", description = "The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I've never seen anything like this curator before.\n\nHe's landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. {name}, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.", sourceObjective = "Etaruk, on the outskirts of the Coldrock Quarry, wants you to kill Curator Insivius.", progress = "Have you done away with the curator?", completion = "The curator and his men must've thought the quarry an easy target for their looting, but you've shown them otherwise, {name}. I am deeply grateful for your help and I'm certain the ancestors will continue to watch over you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11624] = { id = 11624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sky Will Know", description = "I must find out what happened to my master, Farseer Grimwalker!\n\nEarlier, he was observing the magnataur at nearby Magmoth. But one of his grunts just returned, saying that the group had been crushed, and that the farseer was dragged into the depths of the place.\n\nBefore I send you on a suicide mission, I wish to consult with the spirits to learn more.\n\nThere is an air elemental known as Imperean in the ruins of Eldra'nath to the west. She is wise and may give you the information we seek.", sourceObjective = "Speak with Imperean at the Ruins of Eldra'nath.", completion = "You are foolish to come here, little {race}.\n\nWhat is it that you seek?", sourceObjectiveStatus = "unverified-source-field" }
quests[11625] = { id = 11625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trident of Naz'jan", description = "Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen's work!\n\nThey took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace!\n\nI will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!", sourceObjective = "Veehja in Riplash wants you to go to the far northeastern end of the Riplash Ruins. Once there slay Ragnar Drakkarlund and obtain the Trident of Naz'jan from him.", progress = "Do you have the trident?", completion = "Yesssssss!  We will slay the Kvaldir's beast!  I will show these brutes to never cross a priestess of the scale!", sourceObjectiveStatus = "unverified-source-field" }
quests[11626] = { id = 11626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emissary", description = "Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape.\n\nNow you wield it, {race}.  As much as it disgusts me, I will have my revenge on these barbaric giant-men.\n\nTake the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash.\n\nDrive the trident into his flesh and slay him!  Return to whomever sent you when you're done; I wish to see no more of you.", sourceObjective = "Find Leviroth in the waters below the iceberg floating among the northern edge of Riplash Ruins. Use the Trident of Naz'jan to slay him and return to Karuk to the north of Riplash Strand.", progress = "Have you solved the mystery, {name}?  Will my people's spirits be laid to rest?", completion = "My people's spirits can rest in peace.  You've helped me honor my father... perhaps I will one day be as strong as you are.", sourceObjectiveStatus = "unverified-source-field" }
quests[11627] = { id = 11627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boiling Point", description = "Ah, it is information that you crave: the whereabouts and condition of your 'farseer'. He did not see so far as to avoid the trouble which befell him.\n\nNevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me.\n\nNo doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn's pool, and the two have been battling for ages.\n\nGo to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.", sourceObjective = "Imperean wants you to beat Simmer and Churn into submission. Return to her at the Ruins of Eldra'nath when they have submitted.", progress = "You still have yet to beat some sense into those two.", completion = "I am pleased, though no doubt they will still continue to quarrel a bit longer.\n\nHowever, there is something else that you will need to accomplish before you can return to your spirit talker.", sourceObjectiveStatus = "unverified-source-field" }
quests[11628] = { id = 11628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouds of the Scourge", description = "To the northeast looms the Temple City of En'kilah, the Scourge's seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us.\n\nRemaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth.\n\nThe Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.", sourceObjective = "Chieftain Wintergale at Taunka'le Village wants you to bring him 5 Scourged Mammoth Pelts.", progress = "Have you brought the mammoth pelts?", completion = "As much as I dislike bringing such disease-ridden things into the village, they may give us an advantage over our foes.\n\n<The chieftain gestures to Sage Aeire and waves dismissively at the pelts.>\n\nWhile she is preparing the pelts, there is one other element we need to create the cloak.", sourceObjectiveStatus = "unverified-source-field" }
quests[11629] = { id = 11629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Spirit Talker", description = "You have done what was asked, and now I give you that which you desire.\n\nDeliver this primal to the spirit talker back at your Bor'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.", sourceObjective = "Deliver Imperean's Primal to Spirit Talker Snarlfang at Bor'gorok Outpost.", progress = "{name}, you have returned. What did you learn?\n\nWhat is that sound?", completion = "Imperean gave you a primal essence of herself? I can hear its howling winds!\n\nI know a ritual we can make use of it in. We must hurry before her primal rips itself apart!", sourceObjectiveStatus = "unverified-source-field" }
quests[11630] = { id = 11630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad Earth", description = "By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says.\n\nShe'd best be correct. It's our only chance to gather information and plan our counterattack.\n\nYou should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you've finished gathering it.", sourceObjective = "Bring 8 clods of Scourged Earth to Chieftain Wintergale at Taunka'le Village.", progress = "Do you have the earth Sage Aeire needs to complete the cloak?", completion = "<Chieftain Wintergale gingerly accepts the clods of soil you gathered.>\n\nWe should get these into Sage Aeire's hands as soon as possible.\n\n<The chieftain grunts, pretending not to be disturbed by the tainted dirt.>\n\nWe can never know when the Scourge commander will launch the final assault on the village.", sourceObjectiveStatus = "unverified-source-field" }
quests[11631] = { id = 11631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision of Air", description = "Here, {name}, I've attuned the primal to you.\n\nOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.\n\nThe spirit of the wind touches all; with any luck you will be granted a vision.", sourceObjective = "Use Imperean's Primal to perform a ritual at Snarlfang's Totem at Bor'gorok Outpost to gain information concerning Farseer Grimwalker.\n\nAfterward, speak with Spirit Talker Snarlfang.", progress = "When you feel that you have seen enough, return the primal to me.", completion = "They've shackled his spirit. {name}, we have to put an end to his torture!\n\nYou must descend into the bowels of Magmoth and find a way to free him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11632] = { id = 11632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Cold Wind Brings...", description = "You hold the carapace fragment of Ith'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde.\n\nTake your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.", sourceObjective = "Take Ith'rix's Hardened Carapace to High Overlord Saurfang at Warsong Hold.", progress = "What have you got there?", completion = "<Saurfang grins.>\n\nIt looks familiar... The Might of Kalimdor trampled a thousand bugs like this one in the desert of Silithus.\n\nThis is a different place - a different environment - but the result will be the same.\n\n<Saurfang looks you over.>\n\nYou will bring pride and honor to the Horde in Northrend, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11633] = { id = 11633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blending In", description = "Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy's fortifications and leaders.\n\nWhile wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En'kilah abominations will be able to find you if you get too close.", sourceObjective = "Chieftain Wintergale at Taunka'le Village wants you to wear the Imbued Scourge Shroud in the Temple City of En'kilah and scout the Spire of Blood, the Spire of Pain, and the Spire of Decay.", progress = "Have you finished scouting the temples in the Scourge's fortress?", completion = "<Chieftain Wintergale listens as you describe your observations.>\n\nThe information you've gathered will help us to plan our assault on the Temple City. We'll need to find a way to defeat the officers you identified and get into that necropolis.", sourceObjectiveStatus = "unverified-source-field" }
quests[11634] = { id = 11634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wind Master To'bor", description = "You're a tough mother, {name}. I think your talents are better suited elsewhere - like the root of the whole damn problem!\n\n<Razgor points to the west.>\n\nA thousand Scourge, at least four full sized floating death machines and who knows what else.\n\nBut you're gonna find out and then you're gonna handle it... That's right, you're gonna beat the hell out of the Scourge army that's currently beating down our door.\n\nGet to the top of Warsong Hold and report to Wind Master To'bor. He'll be expecting you.", sourceObjective = "Report to Wind Master To'bor at Warsong Hold.", completion = "Ay, mon. I been expectin' you.\n\n<To'bor points west.>\n\nTake a peek. Across dat tundra be death, mon... death.", sourceObjectiveStatus = "unverified-source-field" }
quests[11635] = { id = 11635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farseer Grimwalker's Spirit", description = "You must go to Magmoth to the east.\n\nYou must descend into the depths of their caverns.\n\nYou must speak with Farseer Grimwalker's spirit!", sourceObjective = "Speak with Farseer Grimwalker's Spirit inside of Magmoth.", completion = "Thank you for the reprieve, {class}. If only my true freedom were so easy to attain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11636] = { id = 11636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Carpet Ride", description = "Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da tank to lay down some Horde justice on da Scourge!\n\nDa only tricky part be getting' you der. No way we be sendin' you on our wind riders. Too risky.\n\nYou see dat pixie o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. Once der, talk to Annihilator Grek'lor!", sourceObjective = "Talk to Yanni at Warsong Hold to arrange safe travel to the coast. Speak to Annihilator Grek'lor once you arrive at Garrosh's Landing.", completion = "NO MERCY FOR THE DEAD!\n\nNone of 'em had the guts to stay behind to defend our glorious tanks after Hellscream deemed the coast 'condemned.' It's mostly quiet here, seein' as how the Scourge are formin' up ranks to assault Warsong Hold. Sometimes I get a stray zombie or ghoul, but they don't last very long.\n\n'Course, there's the mist...\n\n<Grek'lor shudders.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11637] = { id = 11637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaganishu", description = "After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu.\n\nThough you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism.\n\nYou must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves.\n\nOnly then will I truly be free.", sourceObjective = "Retrieve Kaganishu's Fetish and use it upon Farseer Grimwalker's Remains.\n\nYou will need to give the fetish to Farseer Grimwalker's Spirit inside of Magmoth.", progress = "Hurry, {class}, use the fetish upon me before it is too late.", completion = "I am freed. Thank you, {name}.\n\nAnd now, I have one final request of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11638] = { id = 11638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return My Remains", description = "{name}, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.\n\nI sense that the spirit talker is still at Bor'gorok Outpost to the west where last I saw her.", sourceObjective = "Deliver Farseer Grimwalker's Remains, which are resting below his spirit, to Spirit Talker Snarlfang at Bor'gorok Outpost.", progress = "You return sooner than I expected. What did you learn?", completion = "Thank you for freeing his spirit from Kaganishu and returning with his remains. We have little to reward you with, but you may take whatever catches your eye.\n\nAnd now, I will return him to the living where he belongs.", sourceObjectiveStatus = "unverified-source-field" }
quests[11639] = { id = 11639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge Upon Magmoth", description = "The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure.\n\nBut you could get revenge for me and the others who fell at Magmoth!\n\nI know that the spirit talker wants you to go in there to save the farseer.\n\nIt's just to the east. Go, {class}... go slay the magnataur and their snobold servants. Regain the outpost's honor!", sourceObjective = "Kill 10 Magmoth Shaman, 5 Magmoth Foragers, 3 Magmoth Crushers, and 3 Mates of Magmothregar. Then, return to Ortrosh at Bor'gorok Outpost.", completion = "The dead are honored by your actions, {name}.\n\n\n\nPerhaps now I can find my way back to being the warrior I once was.", sourceObjectiveStatus = "unverified-source-field" }
quests[11640] = { id = 11640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Power", description = "Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.\n\nAn endless stream of Scourge minions will overrun us if we can't find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, {name}, to slay the high priests and take the scrolls they hold.", sourceObjective = "Bring High Priest Naferset's Scroll, High Priest Talet-Kha's Scroll, and High Priest Andorath's Scroll to Chieftain Wintergale at Taunka'le Village.", progress = "We must get into that necropolis if we're to break through the Scourge and clear a path for the villagers.", completion = "<Chieftain Wintergale reads the words written on the scrolls.>\n\n'Shabtir bakh sokhen.'\n\nWords of the ancient, harsh language used by the Nerubians, and apt ones at that.\n\n'The servant bows to the master's authority.' These are the words that will gain you entry into the necropolis.", sourceObjectiveStatus = "unverified-source-field" }
quests[11641] = { id = 11641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Courageous Strike", description = "From the beginning, I've counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he'd rather tip-toe around according to Sage Aeire's plans.\n\nI'll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you'd be willing to show him that a direct attack can succeed. Storm the Temple City of En'kilah and slay all in your path, {name}.", sourceObjective = "Slay 15 En'kilah Ghouls and 5 En'kilah Necromancers and report back to Durm Icehide at Taunka'le Village.", completion = "You have proven your fearlessness and demonstrated your prowess in combat. I believe you would make a fine taunka warrior. I only wish the chieftain had the same understanding.\n\nWe are fortunate to count you as an ally in our struggle to evacuate the village before it is overrun by the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[11642] = { id = 11642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank Ain't Gonna Fix Itself", description = "We need to get these tanks back up and runnin'! They ain't gonna fix themselves. Mobu's gonna be the one to handle that stuff. Talk to him and see what he needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and I cleave him in two!", sourceObjective = "Speak with Mobu at Garrosh's Landing.", completion = "You're the new tank driver, buddy? Fine by me! We just need to get these things up and running again. Yea, you try to go out into the Plains of Nasam without a tank and you're as good as dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11643] = { id = 11643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobu's Pneumatic Tank Transjigamarig", description = "These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It's the beat down hut next to the stables. You're gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist.\n\nOh yea, buddy, watch out for the mist. The mist is what tore up these shores.", sourceObjective = "Mobu at the Coast of Echoes in the Borean Tundra wants you to recover his Pneumatic Tank Transjigamarig.", progress = "Did you find the P.T.T.?", completion = "Great work, buddy! Now where'd I put those spare parts...", sourceObjectiveStatus = "unverified-source-field" }
quests[11644] = { id = 11644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Strong Metal Plates!", description = "I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh's Landing and at the bottom of the bay.\n\nJust be careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...", sourceObjective = "Mobu at the Coast of Echoes in the Borean Tundra wants you to collect 10 Super Strong Metal Plates.", progress = "Remember, the mist is bad!", completion = "Great work, buddy! Now where'd I put that pneumatic tank transjigamarig.", sourceObjectiveStatus = "unverified-source-field" }
quests[11645] = { id = 11645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty, Stinkin' Snobolds!", description = "Those dirty, stinkin' snobolds... they stole all of my supplies!\n\nWhat's a snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of them. I know, weird!\n\nAnywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the north side of the airstrip.\n\nWhy don'tcha do me a favor and head north to their stupid Magmoth. There's a cash reward if you bring all my stuff back quick!", sourceObjective = "Retrieve 10 boxes of Crafty's Stuff and return them to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Ya got all of my supplies, {class}? I just can't do ANYTHING without all of my stuff!", completion = "Oh, {name}, you're just the best!\n\nHere's your coin as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[11646] = { id = 11646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Borean Inquisition", description = "Listen closely, {name}, for there is not a moment to spare.\n\nYour prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required.\n\nMake your way up to where he is being detained and tell Librarian Normantis that I've sent you to assist him.", sourceObjective = "Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge.", completion = "It was wise of Donathan to send you, {class}.\n\nAs it turns out, I am in need of someone outside the Kirin Tor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11647] = { id = 11647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Cauldrons", description = "The presence of plague cauldrons within the Temple City of En'kilah worries me greatly, {name}. It's clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?\n\nI've prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.", sourceObjective = "Sage Aeire at Taunka'le Village wants you to use her totem to neutralize the East Cauldron, the Central Cauldron, and the West Cauldron in the Temple City of En'kilah.", completion = "<Sage Aeire accepts the totem from you.>\n\nDid the totem work? Its preparation required ancient magics the sages haven't used in generations. Of all the knowledge passed down, only a fraction of it remains in use today.", sourceObjectiveStatus = "unverified-source-field" }
quests[11648] = { id = 11648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Persuasion", description = "It is fortunate you're here, {race}.\n\nYou see, the Kirin Tor code of conduct frowns upon our taking certain 'extreme' measures - even in desperate times such as these.\n\nYou, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information.\n\nDo what you must. We need to know where Lady Evanor is being held at once!\n\nI'll just busy myself organizing these shelves here. Oh, and here, perhaps you'll find this old thing useful....", sourceObjective = "Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor.", progress = "Well? Do you know where Lady Evanor is being held?", completion = "Excellent! It was crucial that we collect that intelligence.\n\nWell done, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11649] = { id = 11649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motes of the Enraged", description = "Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker.\n\nAs you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage.\n\nIn order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.", sourceObjective = "Obtain 5 Tempest Motes and deliver them to Imperean at the Ruins of Eldra'nath.", progress = "Once you have the necessary motes, I will combine a portion of my essence with theirs. The result will get you what you need.", completion = "I regret the loss of those tempests, but my word is my bond... even to a mortal such as yourself.\n\nNow, let us see if we can fashion something of use to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11650] = { id = 11650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Few More Things...", description = "As you may have noticed, we created the airstrip on the southern border of a magnataur den!\n\n<Crafty says something uncharitable about Fizzcrank under her breath.>\n\nThe old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb!\n\nThat's where you come in. I want you to get me everything on this shopping list. Please.", sourceObjective = "Collect Crafty's Tools, an Overcharged Capacitor, and a Handful of Rocknar's Grit. Deliver them to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Why is it that I don't believe you've collected everything on my list?", completion = "Alright, that's more like it! Now all we gots to do is put all this together.\n\nYeah, as if you're going to help me with that.\n\nHold your horses, this'll just take a second now that I've got my tools back!", sourceObjectiveStatus = "unverified-source-field" }
quests[11651] = { id = 11651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanks a lot...", description = "Thanks for all your help, buddy. You can let Grek'lor know the tanks are ready for action. Hopefully you can clean up this place once and for all!", sourceObjective = "Speak to Annihilator Grek'lor at the Coast of Echoes.", completion = "With the current state of our transports and shipping lanes, we haven't been able to get a damned siege engine to Warsong. These tanks are all that we have left from the original expedition. Now that they're operational, you're gonna use 'em to stomp the Scourge offensive at the Plains of Nasam.", sourceObjectiveStatus = "unverified-source-field" }
quests[11652] = { id = 11652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plains of Nasam", description = "Once you're ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here.\n\nUse the tank's weapon arsenal to take down the Scourge army. If you get in a jam, the \"Meatpounder\" will tear 'em up and the land mines will finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks can be found all over the field.\n\nTry to get close enough to that structure in the center and see what's going on.\n\nIf you do all of this and live, go to Hellscream!", sourceObjective = "Use the Horde Siege Tank to destroy 100 Scourge Soldiers and rescue 3 Injured Warsong Soldiers on the Plains of Nasam. You must also discover the identity of the leader of the Scourge assault.\n\nReport to Garrosh Hellscream at Warsong Hold should you succeed.", completion = "Kel'Thuzad? So it's true - Naxxramas returns...\n\nPerhaps I underestimated you, {name}. You've done the Horde a great service. The Warchief would be proud!\n\n\n\nIf Kel'Thuzad is controlling these Scourge, there's no telling what else the Lich King has in store for us... I'll need time to think through this new information, {name}. You are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11653] = { id = 11653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hah... You're Not So Big Now!", description = "That'll do her, chief! So, here's what I want ya to do....\n\nTake my blaster and head north to Magmoth. If we're gonna have a chance at all against those monsters, we need to cut them down to size... so to speak.\n\nIn order to gauge its effectiveness, I need you to slay the magnataur while the blaster's effects are still on it. Any of the crushers or mates will do, but don't bother with the offspring... they're too small to worry about.", sourceObjective = "Test out Crafty's Ultra-Advanced Proto-Typical Shortening Blaster on 5 Magmoth Crushers or Mates of Magmothregar. After you have done so, return to her at Fizzcrank Airstrip.", progress = "You sure that you tested the blaster on enough of those monstrous beasts?", completion = "Whadya mean it didn't work?!\n\nBut... but...\n\n<Crafty begins to sob.>\n\nOkay, we can deal with this. I'm a big girl. Time to think outside the box!", sourceObjectiveStatus = "unverified-source-field" }
quests[11654] = { id = 11654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spire of Blood", description = "As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive.\n\nWhat use would the Scourge have for blood? They've never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you'll be able to discover what the Scourge is planning.", sourceObjective = "Search the Spire of Blood for more information about the Vial of Fresh Blood.", progress = "How... how did you find me?", completion = "<The taunka snow tracker appears weak and barely responds to you.>\n\nI haven't... long. Maybe... maybe you can stop them... before...", sourceObjectiveStatus = "unverified-source-field" }
quests[11655] = { id = 11655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mist", description = "Across the mist to the north you will find Garrosh's Landing. To the south are the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as the Kvaldir.\n\nThese fearsome savages slew all of my people without mercy and drove your people inland.\n\nAll that remains of the tuskarr of Pal'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to kill Kvaldir and recover 8 Tuskarr Relics.", progress = "By blood and honor you must serve... Return the tuskarr relics.", completion = "<Sadness overcomes Waltor.>\n\nRuin... That is all they leave in their wake. They must be taught a lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[11656] = { id = 11656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn in Effigy", description = "Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable.\n\n<Waltor waves a torch-like baton in front of you.>\n\nWith this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh's Landing, north of here, and one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all to see!", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Tuskarr Torch to burn the Kvaldir ships at Pal'ea and Garrosh's Landing. You must destroy the following ships: The Serpent's Maw, The Kur Drakkar, Bor's Hammer and Bor's Anvil.", progress = "Is it done? Are the ships ablaze?", completion = "A show of resistance to the Kvaldir savages might be what is needed to save my people at the other encampments. Perhaps the Kvaldir will rethink their actions should they believe that retribution will come.", sourceObjectiveStatus = "unverified-source-field" }
quests[11657] = { id = 11657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.\n\nCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!", sourceObjective = "Catch 4 torches in a row, then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11658] = { id = 11658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plan B", description = "Okay, don't panic! The blaster might not've worked, but we still have options.\n\n<Crafty snaps her fingers.>\n\nWe're going to divert attention away from the airstrip! To make this work, we'll need a few things first.\n\n<Wobblesprocket looks you up and down appraisingly.>\n\nSteeljaw's caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits.\n\nHead over there and get some outfits off of the dead orcs. Pick up one of their banners, too!", sourceObjective = "Collect 10 Warsong Outfits and a Warsong Banner. Bring them back to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "We'll need lots of their clothes if this is going to work. I'm no seamstress... we'll just have to find something to fit you!\n\nAnd then I'll just add a touch of my engineer genius, and poof, you'll look the part you need to play.", completion = "Nice, but those clothes reek!\n\nPersonally, you'd never catch me dead in such rags. But we're going to have to sort through them and find some that fit your, um... figure.", sourceObjectiveStatus = "unverified-source-field" }
quests[11659] = { id = 11659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Orbs!", description = "They're... bleeding the prisoners... putting the blood... in those globes.\n\n<Grumm's eyes close momentarily and he leans his head back.>\n\nThe blood... taken up to necropolis... to feed blood prince...\n\n<Grumm gasps for breath.>\n\nP-promise... you'll... destroy blood... globes... bring word... to Junek.\n\n<The snow tracker collapses into unconsciousness.>", sourceObjective = "Destroy 5 Blood Globes and report to Snow Tracker Junek at Taunka'le Village.", completion = "I feared they might've captured Grumm, but I never thought they'd do such horrific things to him. I've never seen a warrior survive a losing battle with the Scourge.\n\nThank you for bringing word of his fate, {name}. He was a mighty warrior and we will remember him as such.", sourceObjectiveStatus = "unverified-source-field" }
quests[11660] = { id = 11660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn of the Ancient Mariner", description = "A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal'ea, He oversaw the destruction of both villages and then disappeared into the mist.\n\nIn those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise.\n\nWe need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat.\n\nSeek out mistweavers at Pal'ea, to the south.", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to bring him the Horn of the Ancient Mariner.", progress = "Find the Horn of the Ancient Mariner!", completion = "You must call for Orabus using the Horn of the Ancient Mariner.", sourceObjectiveStatus = "unverified-source-field" }
quests[11661] = { id = 11661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orabus the Helmsman", description = "Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus.\n\nSlay the foul beast and return to me!", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Horn of the Ancient Mariner to summon Orabus the Helmsman. Once summoned, slay Orabus the Helmsman.", progress = "Orabus must be destroyed!", completion = "It seems that the loss of their lieutenant has only stirred the nest. They are more angry and aggressive than before!\n\n<Waltor sighs.>\n\nYou've done what you can here, friend. At the very least you deserve some form of compensation for thinning their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[11662] = { id = 11662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Karuk!", description = "A fellow survivor of Pal'ea known as Karuk has made his way to the main base of the Kvaldir in the Borean Tundra - far to the south where the snow was once bountiful. Karuk hides along the bluffs overlooking Riplash Strand.\n\nSeek out Karuk and let him know what you did for my people here at the Coast of Echoes.\n\nThe safest route to Karuk is through your fortress. From Warsong Hold, take the road south and follow it around until you reach Riplash Strand.", sourceObjective = "Seek out Karuk at Riplash Strand.", completion = "Waltor was wise in sending you to me, {race}. The gods smile down upon those that mete justice. You will be he that doles out punishment to the wicked!", sourceObjectiveStatus = "unverified-source-field" }
quests[11663] = { id = 11663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing Intelligence", description = "Thank you, {class}! The information you've extracted is of vital importance to the Kirin Tor.\n\nReturn at once to Donathan as we make plans for the rescue of Lady Evanor.", sourceObjective = "Normantis has asked you to report to Librarian Donathan on Amber Ledge.", completion = "Forgive me, {name}. I know that was unpleasant work.\n\nWere it not for the desperation of our circumstance I'd never have asked you to assist us in such a manner.\n\nSo... what have you discovered?", sourceObjectiveStatus = "unverified-source-field" }
quests[11664] = { id = 11664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaping the Mist", description = "I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others?\n\nI wonder, how far has the mist crept, stranger? Has it overtaken this whole continent?\n\nWould you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.", sourceObjective = "Follow Mootoo the Younger out of the mist. Speak to Elder Mootoo should you successfully save Mootoo the Younger.", progress = "You found my daughter?", completion = "It is whispered in the winds, friend. Your name is known to the elements. You have done a great service to Mootoo on this day and you shall be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[11665] = { id = 11665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisks in the City", description = "Hello <lad/lass>.  I'm glad you've stopped by to talk to this old man--there's trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.", sourceObjective = "Bring a Baby Crocolisk to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Catch any crocs in the sewers yet?", completion = "What a mean little creature!  I'm sure the Rokk will make something tasty with him.\n\nI'm just kidding, of course.\n\n<Old Man Barlo winks slyly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11666] = { id = 11666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait Bandits", description = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.", sourceObjective = "Bring a Blackfin Darter to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "How's the fishing today, lad?", completion = "Well look at that... you caught a big one!  This old man is eating in style tonight.", sourceObjectiveStatus = "unverified-source-field" }
quests[11667] = { id = 11667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.\n\nYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", sourceObjective = "Catch the World's Largest Mudfish and bring it to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Tell me you caught him.  Please tell me you caught that son of a carp.", completion = "There he is!  I'd know that scar anywhere.\n\nTo be completely honest, I thought he'd be... bigger.  Well, I suppose I'll let him go and try again another day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11668] = { id = 11668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrimpin' Ain't Easy", description = "There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?\n\nShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", sourceObjective = "Bring 10 Giant Freshwater Shrimp to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "What's the catch of the day, lad?", completion = "You are skilled with both the hook and knife.  Hand those sweet tidbits over, and I'll let you have a taste.", sourceObjectiveStatus = "unverified-source-field" }
quests[11669] = { id = 11669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felblood Fillet", description = "This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.", sourceObjective = "Bring a Monstrous Felblood Snapper to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "The felblood is a marvel of evolution.  It can survive in any water and even lava, and fishermen are its only natural predator.\n\nAny luck with your prey?", completion = "That is the biggest, ugliest fish I've seen.  I can't even imagine what you used for bait.\n\nJust set the beast on the ground, and I'll deal with it once I'm sure it's dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11670] = { id = 11670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Was The Orcs, Honest!", description = "With all of those outfits you, er, recovered, I fashioned a Warsong orc disguise. I had the genius idea of combining it with some old stuff that I had left hanging around from last Hallows' End, so it should be foolproof!\n\nHere, in this sack is the disguise and the banner you recovered. Head down into the bowels of Magmoth and slay the magnataur chieftain, Magmothregar.\n\nIf you're going to convince them to turn their attention on the Warsong orcs, you'll need to plant the banner while disguised.", sourceObjective = "While disguised as a Warsong orc, plant the Warsong Banner in the corpse of Magmothregar. Then, return with the disguise to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "It's all over then? You've done the dirty deed and framed the orcs at Bor'gorok Outpost?", completion = "Holey moley, you did it!\n\nAlright, now those pesky magnataur and their snobold flunkies should turn their attentions on the Horde.\n\nHow can I ever repay you, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11671] = { id = 11671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Race Against Time", description = "So it's true. They have her.\n\nIt's clear what must be done, {race}. She WILL be saved.\n\nI must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact.\n\nWe've customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you've collected the key.\n\nHurry, {name}. Lady Evanor is suffering!", sourceObjective = "Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds.", progress = "Have you collected Salrand's key?", completion = "Broken? \n\nLet me have a look....", sourceObjectiveStatus = "unverified-source-field" }
quests[11672] = { id = 11672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlistment Day", description = "You've come to enlist, right?  Normally you'd have to stand in line like the other recruits.  Normally you'd be out of luck because the recruitment ledger's gone missing and I can't process anyone until the new books get here.\n\nFortunately for you, {name}, I've heard about you and what you did in Outland.  To be honest, you're a cut above these poor saps.  Lines aren't for you.\n\nGo to the barracks and speak to General Arlos.  He'll be more than happy to meet with someone of your caliber.", sourceObjective = "Meet with General Arlos inside the barracks in Valiance Keep.", completion = "We've been expecting your arrival, {name}.  Welcome to Northrend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11673] = { id = 11673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Outa Here!", description = "I knew they'd send someone for me sooner or later... turned out to be later, of course.\n\nI came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I'd make a tasty snack for Magmothregar.\n\nWait... what?! They didn't send you?!\n\nDID THEY FORGET ABOUT ME?!\n\nOkay, you're here now and that's all that matters.\n\nAs soon as you break this chain we'll make our way back to the airstrip. Then you can tell Fizzcrank I'm safely back.\n\nIf he remembers me, that is.", sourceObjective = "Escort Bonker Togglevolt to safety and then report in with Fizzcrank Fullthrottle at Fizzcrank Airstrip.", completion = "Huh? What?\n\nBonker who?\n\nI've no idea who you're talking about, but I'll take your word for it. If you rescued him or her from the pit of Magmoth then I suppose you deserve a reward.\n\nLet me see what I've got lying around in here....", sourceObjectiveStatus = "unverified-source-field" }
quests[11674] = { id = 11674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage Highmesa is Missing", description = "There are many new mysteries walking the lands now. One of our sages, Highmesa, has foolishly gone north with only one longrunner to investigate something strange near the Dens of Dying.\n\nWhat are the dens, you ask? They are a sacred place to the magnataur, where they go in their old age to die. She saw something fall from the sky near them a few days ago.\n\nIf you would be friend to the taunka, I would have you find and help her. She is not so stubborn that she will not accept your aid.", sourceObjective = "Find Sage Highmesa near the Dens of Dying.", completion = "The greatmother sent you. She must be disappointed in me.\n\nBut when I saw the great object fall from the sky, I could not wait for a full group of longrunners and snow trackers to accompany me. Knowledge waits for no one.", sourceObjectiveStatus = "unverified-source-field" }
quests[11675] = { id = 11675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Death", description = "The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery.\n\n{race}, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.", sourceObjective = "Destroy 10 Plagued Magnataur and then return to Sage Highmesa south of The Dens of Dying.", progress = "I still see too many of them for your efforts to have been very effective. A true {class} would finish the job.", completion = "What else can we do but ease their suffering? In any case, they came here to die, so do not mourn them. At least you have given them some dignity.\n\nNow we must put an end to that which is causing the plague.", sourceObjectiveStatus = "unverified-source-field" }
quests[11676] = { id = 11676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merciful Freedom", description = "The soldiers that they didn't kill are being held in cages scattered across this farmland. Through some thievery we've managed to find a few keys, but we're unable to get close enough to any prisoners without being attacked.\n\nWe need your \"talents\" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.", sourceObjective = "Shadowstalker Canarius at Warsong Farms Outpost wants you to free 5 Scourge Prisoners.", progress = "Save those prisoners!", completion = "Each prisoner saved is one less undead aberration that we have to deal with, {name}. You've done a great service for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11677] = { id = 11677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Plague", description = "I'm convinced that the plague is being caused by something in the caves up there.\n\n{class}, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens.\n\nFind the source of the plague and throw them into it.", sourceObjective = "Sage Highmesa, standing just south of The Dens of Dying, has asked you to use Highmesa's Cleansing Seeds at a Den of Dying Plague Cauldron to neutralize it.", progress = "Either cave should do, {class}. Quickly, use the seeds to end the plague!", completion = "<The sage hangs her head and sighs in relief.>\n\nThis is a good start. If only that were our only problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[11678] = { id = 11678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Bristlehorn", description = "Bristlehorn should have returned by now.\n\nThe other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He's impetuous and has likely gotten himself into trouble.\n\n{name}, go to that place and find him, please.", sourceObjective = "Find Longrunner Bristlehorn at Talramas.", completion = "I am... not... long for this... world, little {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11679] = { id = 11679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging the Key", description = "Delays, delays... the one thing we cannot afford right now!\n\nAs much as I hate to disturb Lord Surristrasz, he's our only hope of saving our beloved Evanor.\n\nBring him the key fragments and hope that his mood is favorable.\n\nHurry, {class}, our assault team is waiting.", sourceObjective = "Donathan wants you to speak to Surristrasz on Amber Ledge.", progress = "You dare approach me, mortal?\n\nFor the sake of your unborn children, pray that your cause is worthwhile.", completion = "The frivolous games you play here are of no consequence....\n\nYou and your Dalaran allies pick at loose threads while the fabric of this world's future is being shredded.\n\nStill, this may provide my drakes some needed amusement.\n\nShow me this key....", sourceObjectiveStatus = "unverified-source-field" }
quests[11680] = { id = 11680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Wing", description = "The key is forged anew.\n\nNow heed my counsel, {race}. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable.\n\nNow, off with you.", sourceObjective = "Give Salrand's Key to Warmage Anzim when you are ready to free Evanor.\n\nProvided item:", completion = "This is it, the key is ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[11681] = { id = 11681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing Evanor", description = "At last, we attack!\n\nOnce we've cleared the platform I'll use the key.\n\nYou are to ensure that Lady Evanor remains safe after her release.\n\nHurry now, let us be off!", sourceObjective = "Anzim on Amber Ledge wants you to fly with his war mages to free Lady Evanor at Beryl Point. You are then to report to her in the mage tower on Amber Ledge.", completion = "Your heroic efforts shall not be forgotten, {class}.\n\nPlease, accept this with my sincere gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11682] = { id = 11682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonspeak", description = "I am aware of your recent deeds here, {name}, and again I thank you.\n\nAs for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues....\n\nAzeroth needs you. The region just west of here is the center of an urgent crisis.\n\nI'll leave the details to Lord Surristrasz. You must speak with him at once.\n\nGood luck, friend of Dalaran.", sourceObjective = "Lady Evanor has sent you to speak with Surristrasz on Amber Ledge.", completion = "So, {race}, we speak again.\n\nWhen you've heard my words you may wish we had not.", sourceObjectiveStatus = "unverified-source-field" }
quests[11683] = { id = 11683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Necropolis", description = "The fallen necropolis to the west can only be assumed to still be filled with Scourge.\n\nWhile you are at Talramas, {class}, I would ask that you dispatch all of the Lich King's servants that you find within and in the surrounding pools where it fell.", sourceObjective = "Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Sage Highmesa just to the south of The Dens of the Dying.", completion = "Thank you, {name}.\n\nThe Lich King and his Scourge are a blight upon Northrend. We must not stop until they are all truly dead, and his existence is put to an end!", sourceObjectiveStatus = "unverified-source-field" }
quests[11684] = { id = 11684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Sinkholes", description = "Can you feel the tremors in the earth?\n\nThe Scourge's nerubians are on the move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out.\n\n<The taunka elder offers you a worn map.>\n\nPerhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.", sourceObjective = "Greatfather Mahan at Taunka'le Village wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.", progress = "Have you marked the locations of the sinkholes?", completion = "<Greatfather Mahan accepts the map, but makes no move to examine it..>\n\nWe'll be able to use your information later, once we're prepared to carry out the plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[11685] = { id = 11685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Elements", description = "Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help.\n\nSoutheast of the village, near the coast beyond the Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.", sourceObjective = "Bring 5 Elemental Hearts to Wind Tamer Barah at Taunka'le Village.", progress = "Greatfather Mahan tells me you have agreed to help collapse the tunnels.", completion = "These should be enough to form the core of a mighty elemental, but stone alone will not give my elemental life.", sourceObjectiveStatus = "unverified-source-field" }
quests[11686] = { id = 11686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warsong Farms", description = "According to Luther's notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field.\n\n<Ickoris shudders.>\n\nThose monsters were once orcs... tauren...\n\nWe need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west of us, and the old Warsong Slaughterhouse, north of us.\n\nReturn to me once you've scouted 'em out.", sourceObjective = "Shadowstalker Ickoris at Warsong Farms Outpost wants you to scout Warsong Granary, Torp's Farm, and Warsong Slaughterhouse.", progress = "Have you searched the farms?", completion = "This is far worse than what was noted in Luther's journal. They've got this place covered in Scourge and are infecting everything they touch.\n\n<Ickoris nods.>\n\nIt gets worse - if you can imagine such a thing...", sourceObjectiveStatus = "unverified-source-field" }
quests[11687] = { id = 11687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doctor and the Lich-Lord", description = "There are two... that must... be killed.\n\nThe doctor and... the lich-lord... are above. Find them... destroy them... before....\n\n...it is too... late....", sourceObjective = "Destroy Doctor Razorgrin and Lich-Lord Chillwinter. Then, return to Sage Highmesa just to the south of The Dens of Dying.", completion = "Bristlehorn is dead?!\n\nI should never have let him go there by himself.", sourceObjectiveStatus = "unverified-source-field" }
quests[11688] = { id = 11688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damned Filthy Swine", description = "Just look at 'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, {race}. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off 'em, else there'll be nothin' left to cure!\n\nGet out there and send those swine to their graves - permanently!", sourceObjective = "Farmer Torp at Warsong Farms Outpost wants you to kill 10 Unliving Swine.", progress = "I need more time! Keep those swine off my kodos!", completion = "I think I've got it, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11689] = { id = 11689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return with the Bad News", description = "The greatmother will need to know, {name}.\n\nWill you please return to Taunka'le? Tell her that I will be following shortly.", sourceObjective = "Speak with Greatmother Taiga at Taunka'le Village.", completion = "What word do you bring from Highmesa?\n\n<You explain what you know and give the greatmother the bad news concerning Longrunner Bristlehorn.>\n\nMy... my grandson!\n\n<The greatmother fights to keep control of her emotions.>\n\nHe died an honorable death like a true taunka!\n\nYou were the last to be with him, {name}, so he shall always be a part of you. I give you my thanks for completing his last wishes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11690] = { id = 11690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring 'Em Back Alive", description = "Take this riding snaffle, {name}. You'll notice that I've placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. They'll be weak so you'll need to gently direct 'em here.\n\nBring my babies back, {name}!\n\nOne last thing, you've got ten minutes! That's how long the antidote will remain effective inside that snaffle.", sourceObjective = "Farmer Torp at Warsong Farms Outpost wants you to rescue 8 Infected Kodo Beasts.", progress = "Get them out of those Scourge infested fields!", completion = "You're a true hero, {name}. My kodos would have died out there without you. You have my thanks and the thanks of all the soldiers and journeymen that will use these kodos to strengthen our presence in Northrend!", sourceObjectiveStatus = "unverified-source-field" }
quests[11691] = { id = 11691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Ahune", description = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  {name}, you will be the fist of the Earthmother.\n\nTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.\n\nIf fortune is with us, then, perhaps, we can defeat him.\n\nPrepare yourself, {name}.  If Ahune comes to face us, then his fury will be great.", sourceObjective = "Bring the Earthen Ring Magma Totem to the Ice Stone.", progress = "This shard of ice echoes the deep, cracking rumble of invading glaciers.  Its cold turns your thoughts to a lifeless, endless winter.", completion = "The magma totem bursts into three separate flames as it is brought near the ice stone.  The stone shimmers, then is gone...", sourceObjectiveStatus = "unverified-source-field" }
quests[11692] = { id = 11692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check in With Bixie", description = "You're a proven <hero/heroine>. I have another problem!\n\nMy boss, Tinky, went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! Tinky's the only one that can fix it and we really need it working one-hundred percent.\n\nYou think you could find them? Bixie said something about following some old magnataur to a place called The Dens of Dying.\n\nI'm guessing that's where you'll find them.\n\nYou can catch a ride out there by talking with Kara Thricestar at the runway.", sourceObjective = "Mordle Cogspinner has asked you to find Bixie Wrenchshanker to the south of The Dens of Dying.", completion = "What do you need, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11693] = { id = 11693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Great... Plagued Magnataur!", description = "Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die.\n\nOf course, we had no idea that they were going to get plagued when they went in there. We can't have plagued things just roaming about; it's not healthy.\n\nSay, why don't you put down a number of those things while I figure out what our next step should be?", sourceObjective = "Kill 10 Plagued Magnataur and then return to Bixie Wrenchshanker to the south of The Dens of Dying.", progress = "Doesn't look like enough of the plagued magnataur have been put down yet, {class}.\n\nThink you could take care of a few more before coming back?", completion = "Nice work, but I'd grab a shower the next chance you get.\n\nNow, let's really deal with the problem out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11694] = { id = 11694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Something Going On In Those Caves", description = "So, while you were out taking care of those plagued beasts, I took a peek inside the caves up there.\n\nThere are cultists in there plaguing them!\n\nThey have some sort of noxious concoction brewing in a cauldron. I have a powder that I normally use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize their brew!\n\nTake it up to one of those caves and see if it works.", sourceObjective = "Bixie Wrenchshanker, skulking just to the south of The Dens of Dying, has asked you to use Bixie's Inhibiting Powder at a Den of Dying Plague Cauldron to neutralize it.", completion = "I knew you had it in you. Now there's something else that I need to ask you to take care of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11695] = { id = 11695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horn of Elemental Fury", description = "I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we'll need help and a bit of luck.\n\nLegend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if the legend is true, but it's our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.", sourceObjective = "Reclaim the Lower Horn Half and Upper Horn Half from Chieftain Burblegoggle and Chieftain Gurgleboggle and bring them to Wind Tamer Barah at Taunka'le Village.", progress = "Were you able to find the horn? Was the legend true?", completion = "<Barah accepts the pieces of the horn from you and begins trying to fit them together.>\n\nStormhoof would be proud of you, {name}. Perhaps when we've dealt with the Scourge, I will take the horn with me on a pilgrimage to Stormhoof's tomb.", sourceObjectiveStatus = "unverified-source-field" }
quests[11696] = { id = 11696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune is Here!", description = "{name}, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, {name}.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.", sourceObjective = "Find Luma Skymother in the Slave Pens.", completion = "The cold of Ahune spreads through these caverns, {name}; a seed of the frigid death that awaits us if he gains his full strength.  I thank the Earthmother for sending you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11697] = { id = 11697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rats, Tinky Went into the Necropolis!", description = "I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west.\n\nI'm 100% certain that those cultists came from inside that thing, which means I'm now 100% certain that Tinky's in trouble!\n\nShe's the airstrip's number one engineer. Without her we're doomed!\n\nI'd find her myself, but one of those things got in a swipe on my leg before I could vanish again. {name}, if anyone can get her out, it's you!", sourceObjective = "Find Tinky Wickwhistle inside Talramas.", completion = "Hey there! Who are you?\n\nBixie sent you? Excellent, let's get me out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[11698] = { id = 11698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might As Well Wipe Out the Scourge", description = "If the cultists up in those caves survived the crash, then that fallen necropolis to the west can only be assumed to still be filled with Scourge. There're probably lots of them out in front of it in the pools, too!\n\nWhile you're at Talramas, {class}, do you think you could dispatch all of the Lich King's flunkies that you find there?", sourceObjective = "Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Bixie Wrenchshanker just to the south of The Dens of the Dying.", completion = "Thanks, {name}.\n\nThe Lich King and his Scourge are really scary, but we can't stop until they are all lying still in new graves!", sourceObjectiveStatus = "unverified-source-field" }
quests[11699] = { id = 11699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Stuck in this Damned Cage... But Not For Long!", description = "The cultists magicked me into this cage and there's no door to it. Little did they know that I'm the chief transmatter engineer for the airstrip!\n\nWith your help, and a little elbow-grease, I won't be in here for long.\n\nI'm going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top.\n\nWith all of that stuff, I should be able to make a port device to get back to Fizzcrank's and escape the gnome way!", sourceObjective = "Collect an Engine-Core Crystal, a Magical Gyroscope, and a Piloting Scourgestone. Deliver them to Tinky Wickwhistle at Talramas.", progress = "You got all of that stuff?", completion = "Outstanding! Now just a little modification here, and a tweak there....", sourceObjectiveStatus = "unverified-source-field" }
quests[11700] = { id = 11700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Bixie Know", description = "My evil twin's out there somewhere now.\n\nI'm pretty sure that she's not back at the airstrip. In fact, wherever she ended up, it's colder there than here. But I could only 'feel' her for a moment.\n\nOh well, I'll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I'll meet her back there?\n\nThanks, {name}!", sourceObjective = "Speak with Bixie Wrenchshanker just south of The Dens of Dying.", completion = "Tinky's got an evil twin?!\n\nWell, if she says she's okay, and that she'll be able to get herself back to the airstrip soon, that's good enough for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[11701] = { id = 11701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Airstrip", description = "Okay, I think I'm going to start making my way back to the airstrip, too. Of course, I'm moving a little slower with this leg injury.\n\nSay, do you think you could get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that there'll be a reward in it for you.\n\nThanks, {name}!", sourceObjective = "Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip in Borean Tundra.", completion = "That's quite a tale, {name}. With all of the problems out here, it's a wonder that the airstrip hasn't been wiped out already.\n\nBut, thanks to you, there's one less adversary to worry about.\n\nI put aside some special things for just such an occasion as this. Why don't you take your pick?", sourceObjectiveStatus = "unverified-source-field" }
quests[11702] = { id = 11702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Mrgl-Mrgl", description = "Dis is gonna sound weird, {class}, but dere be a murloc askin' for our help!\n\nHe goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and his people been run outa dere village and wantin' you to come save dem.\n\nYou find him by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin Retreat.", sourceObjective = "Speak with King Mrgl-Mrgl at Winterfin Retreat.", completion = "Finally, help! And by the looks of you, Horde.\n\nThat's alright... your people are very skilled in the art of combat. We're going to need a lot of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11703] = { id = 11703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Getry", description = "The Scourge agent that's overseeing the abduction and transformation of Horde soldiers into undead monsters is using the northwest farm as a spawning glade. Shadowstalker Getry has been staking out that monster for the past week and has gathered some vital information that might allow us to end this menace.\n\nGet to Getry and see if you can help him put a stop to this Scourge assembly line. You'll find Getry at the abandoned tower on the northwest border of these farms.", sourceObjective = "Find Shadowstalker Getry at Warsong Farms.", completion = "<Getry looks you over.>\n\nThis is all Ickoris could send?", sourceObjectiveStatus = "unverified-source-field" }
quests[11704] = { id = 11704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Mrgl-Mrgl", description = "This is the weirdest thing, {class}, but there's a murloc asking for our help!\n\nHe goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It would seem that he and his people have been run out of their village and they want someone to come save them.\n\nThat someone is you!\n\nYou'll find Winterfin Retreat, and the king, by heading west down the road until you come to the cliffs. Head down to the water line near the Blistering Pool.", sourceObjective = "Speak with King Mrgl-Mrgl at Winterfin Retreat.", completion = "Finally, help! And by the looks of you, Alliance.\n\nThat's good... your people are very skilled in the art of combat. We're going to need a lot of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11705] = { id = 11705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foolish Endeavors", description = "This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions?\n\n<Getry sighs.>\n\nIf Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh?\n\nWhen you're ready we will descend and face Varidus.\n\nIf we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.", sourceObjective = "Help Getry defeat Varidus the Flenser at Warsong Farms.\n\nReport to Garrosh Hellscream should you succeed.", completion = "And you returned victorious, just as I thought! I told Saurfang you'd be fine.\n\n<Hellscream grunts knowingly.>\n\nPerhaps this will show that old dog that he doesn't have all the answers, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[11706] = { id = 11706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Collapse", description = "I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn's call when you stand near the southernmost sinkhole in the Geyser Fields.\n\nThe quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn't be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn't break the back of their assault, the defeat of their leader surely will.", sourceObjective = "Wind Tamer Barah at Taunka'le Village wants you to collapse the Nerubian sinkholes using the Horn of Elemental Fury and defeat Lord Kryxix.", progress = "Have you unleashed Alluvius and destroyed the Nerubian assault?", completion = "Your efforts against the Nerubians have given us a reprieve from the overwhelming Scourge assault. Thanks to your accomplishments, we can strike at the the Scourge fortress to the northeast without fear of attack from the west.\n\nAs for the horn, I will safeguard it until next we need its power. Stormhoof gave his life to secure the horn and we cannot suffer its loss again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11707] = { id = 11707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distress Call", description = "Oh good, you're {name}, right?\n\nWe need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station!\n\nIt's madness I tell you, madness!\n\nYou've got to head up there and talk to old man Fullthrottle a.s.a.p.!", sourceObjective = "Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip.", completion = "I see that Skyhopper finally got around to sending help. And none too soon I might add!\n\nWelcome, brother, we need your help badly!", sourceObjectiveStatus = "unverified-source-field" }
quests[11708] = { id = 11708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mechagnomes", description = "Now that you're here, it's time for me to tell you the full story of what's going on.\n\nAfter you've heard my tale, go outside and find my second-in-command, Jinky Wingnut. She'll handle everything from here on out.", sourceObjective = "Listen to Fizzcrank Fullthrottle's tale and then find Jinky Wingnut at Fizzcrank Airstrip.", progress = "Hello there.", completion = "The old man sent you to me, huh? He tell you everything that's going on out here?\n\nGood... let's take care of business then!", sourceObjectiveStatus = "unverified-source-field" }
quests[11709] = { id = 11709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nork Bloodfrenzy's Charge", description = "While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange.\n\nYou are dismissed, {name}.", sourceObjective = "Speak to Warden Nork Bloodfrenzy at Warsong Hold in Borean Tundra.", completion = "<Nork scoffs.>\n\nPrisoners? These aren't prisoners. They're cowardly dogs! Just look at 'em. Did you know that without exception, every single one of these yellow-bellied \"soldiers\" came to our gates and surrendered their arms and armor?\n\nFrom what we've been able to gather, these men and women are discharged and sent back to their homes if captured by us.\n\n<Nork spits.>\n\nPathetic...", sourceObjectiveStatus = "unverified-source-field" }
quests[11710] = { id = 11710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's the Matter with the Transmatter?", description = "There're spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned.\n\nI'd hate to see another accident....", sourceObjective = "Collect 15 Fizzcrank Spare Parts and deliver them to Mordle Cogspinner at Fizzcrank Airstrip.", progress = "It's going to take a lot of spare parts to keep this thing running.\n\nPlease tell me that you've returned with everything we need.", completion = "That's great, {class}! These parts look like they're in serviceable condition.\n\nNow if I could only figure out how to fix this blasted thing....", sourceObjectiveStatus = "unverified-source-field" }
quests[11711] = { id = 11711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coward Delivery... Under 30 Minutes or it's Free", description = "We're seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy.\n\n<Nork snorts as he laughs.>\n\nI want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands.\n\nReport to Scout Tungok on the east road once the delivery has been made.", sourceObjective = "Take the Alliance Deserter to the crossroads east of Warsong Hold and fire your Warsong Flare Gun to signal the Alliance.\n\nReport to Scout Tungok once you have successfully delivered the Alliance Deserter to their destination.", progress = "<Tungok grunts.>\n\nDid you take care of the deserter?", completion = "Good job, {name}. That's one less filthy, useless, Alliance scum-bag that we'll have to provide for...\n\nIf you're lookin' for more work, the tauren and blood elf nearby need some help.\n\n'Course we've got our own set of problems to deal with out here as well...", sourceObjectiveStatus = "unverified-source-field" }
quests[11712] = { id = 11712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Cursive", description = "If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the \"Curse of the Flesh\", and now they're robots!\n\nWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.\n\nWe're hoping that this stuff will cure them and allow us to lock onto them to port 'em out of there.\n\nWhaddya say, {name}?", sourceObjective = "Jinky Wingnut at Fizzcrank Airstrip has asked you to use the Re-Cursive Transmatter Injection on 6 Fizzcrank Mechagnomes.", completion = "You did it... it worked!\n\nI can't believe you were able to save so many. We're fortunate to have you around here!", sourceObjectiveStatus = "unverified-source-field" }
quests[11713] = { id = 11713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Sinkholes", description = "Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford to wait any longer for their information, so I'm going to need someone to check out the sinkholes on foot.\n\nI understand the dangers involved, and I'll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.", progress = "Have you marked the locations of the sinkholes?", completion = "<Abner accepts the map from you, then examines it closely.>\n\nGreat! This is all the information we need to begin the operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[11714] = { id = 11714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermin Extermination", description = "Perhaps you'd be interested in helping me clean up these fields? They're littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, they're all over the damned place. The stink alone is making my life hell!\n\nTake care of the vermin for me and I'll make it worth your while, {name}.", sourceObjective = "Scout Tungok at the Bloodspore Plains in the Borean Tundra wants you to kill 8 Bloodspore Harvesters, 5 Bloodspore Firestarters and 2 Bloodspore Roasters.", progress = "This job stinks...", completion = "A job well done, {name}! Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11715] = { id = 11715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Project", description = "I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we'll have to collect the fuel for the device some other way.\n\nOut in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine.\n\nSimply deploy the collector near the rig, and it will pump and store the oil in its tank.", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to collect 8 Barrels of Oil using the Portable Oil Collector.", progress = "Do you have that fuel?", completion = "<Abner sets about draining the fuel tank of the collector.>\n\nDistilling this by hand is going to be messy, but I'll have it taken care of soon. In the meantime, we'll need one more material to complete the machine.", sourceObjectiveStatus = "unverified-source-field" }
quests[11716] = { id = 11716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wondrous Bloodspore", description = "We are witnessing something amazing here, {race}. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz.\n\nI have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You'll find them near the larger plants surrounding us.\n\nBe wary of their guardians! The kobolds won't give them up easily!", sourceObjective = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels.", progress = "The tests must continue!", completion = "Lovely! Just lovely!\n\n<Laurith applies a sprinkling of pollen to one of the bloodspore carpels and then utters an incantation.>\n\nHrmph... I don't understand. Unless... Why of course!", sourceObjectiveStatus = "unverified-source-field" }
quests[11717] = { id = 11717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen from the Source", description = "It's obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth's internal system that acts as a catalyst for this pollen to work. It's all starting to make sense now, {name}. That's why the kobolds don't kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!\n\nWell we'll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?", sourceObjective = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen.", progress = "The pollen is the key!", completion = "A-ha!\n\n<Laurith sprinkles the moth pollen onto the bloodspore carpels.>\n\nLook at that!", sourceObjectiveStatus = "unverified-source-field" }
quests[11718] = { id = 11718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bot in Mammoth's Clothing", description = "I've reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend's biting cold.\n\nI've devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we'll be able to unleash it on the Nerubians!", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides.", progress = "Bring those hides as quickly as possible! I won't be able to finish the machine without them!", completion = "<Abner inspects the hides, coughing at all the dust rising from them.>\n\nDon't these animals even try to keep clean? Some of these are absolutely filthy. Well, I guess I'd better get started cleaning them. It's not like anyone's got spare time around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11719] = { id = 11719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Test Subject", description = "<Laurith looks you over as if to size you up.>\n\nSo we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway?\n\nDon't you worry, {name}! Just take this sample and rub it all over your face.", sourceObjective = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.", progress = "Don't be afraid.", completion = "Primal Mighthorn will be delighted! This is better than even I expected!\n\nPerhaps it's time that I told you the truth.", sourceObjectiveStatus = "unverified-source-field" }
quests[11720] = { id = 11720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Invasion of Gammoth", description = "Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left...\n\nWe aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail...\n\nSpeak to Primal Mighthorn now.", sourceObjective = "Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", completion = "The bloodspore that you collected might just be enough to give us an edge against the magnataurs of Gammoth - with your help, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[11721] = { id = 11721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammothra the Tormentor", description = "Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.\n\nTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.", sourceObjective = "Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", progress = "The powder can be used to weaken all magnataur. It is why the rat men of the area guard it so closely.", completion = "A job well done, {name}! Would you honor Laurith and I by taking the head of the beast and presenting it to Hellscream? He will be extremely pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[11722] = { id = 11722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophies of Gammoth", description = "We cannot take all of the credit for this Horde victory, {name}. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.\n\nHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.", sourceObjective = "Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.", progress = "Back so soon?", completion = "<Hellscream picks up the head of Gammothra with one arm and spits in its face.>\n\nThey will learn, {name}... They will all learn. The Horde is not to be trifled with...", sourceObjectiveStatus = "unverified-source-field" }
quests[11723] = { id = 11723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deploy the Shake-n-Quake!", description = "Behold, the machine that will save us from the Nerubian threat!\n\n<Abner beams with pride as he presents the finished bot.>\n\nTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.\n\nDon't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.", progress = "Well, have you deployed the Shake-n-Quake 5000 yet?", completion = "<Abner listens eagerly as you report your success and the success of the Shake-n-Quake 5000.>\n\nFizzcrank will be delighted to hear the news! And who knows, perhaps we'll make a mechanic of you yet!", sourceObjectiveStatus = "unverified-source-field" }
quests[11724] = { id = 11724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massive Moth Omelet?", description = "This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!\n\nCollect the egg and take it to the expectant Bloodmage.", sourceObjective = "Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra.", progress = "Greetings!", completion = "Alkor is no more, eh? A pity... As for the egg, we have no real use for it anymore. We've got much bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
quests[11725] = { id = 11725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Pilot Tailspin", description = "I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.\n\nNo, it's just that it's my responsibility to lead a mission of such import.\n\nI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.\n\nThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.\n\nFind Tailspin, {name}.", sourceObjective = "Locate Iggy \"Tailspin\" Cogtoggle in the Geyser Fields.", completion = "Thank goodness. It was terrible.\n\nThere was a bright flash on the ground, and then, the next thing I know, the squadron's going down! I'm hurt pretty badly, so I haven't had a chance to comb the site for other survivors, but something tells me I don't think there will be many.\n\n<Iggy grimaces in pain.>\n\nWill you help me complete my mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[11726] = { id = 11726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Bit of Spice", description = "The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process.\n\nI have a plan to recover that microfilm, but I need your help to make it work.\n\nTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.", sourceObjective = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches.", progress = "Do you have those spice pouches?", completion = "<Iggy holds his nose as he empties the spice pouches and addresses you in a nasal voice.>\n\nNow that we have what we need, I'll combine it with my emergency rations to create a bait for the wolves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11727] = { id = 11727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time for Heroes", description = "It's good to have you among us, {name}.  We've all heard of your past deeds.\n\nAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.\n\nI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.\n\nReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.", sourceObjective = "Report to Sergeant Hammerhill at Valiance Keep.", completion = "By Magni's beard!  Looks like the heavy artillery's arriving.", sourceObjectiveStatus = "unverified-source-field" }
quests[11728] = { id = 11728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupus Pupus", description = "Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait.\n\nSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.\n\nI'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.", sourceObjective = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm.", progress = "Have you recovered the microfilm?", completion = "<Iggy holds his nose as he accepts the microfilm from you.>\n\nYuck, well, we've complied with section 8.2, paragraph B of the emergency protocol here and recovered the film. Nothing in the protocol says I'm responsible for cleaning it, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[11729] = { id = 11729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultrasonic Screwdriver", description = "The unit you just dismantled had this inside of its mechanical innards.\n\nIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?", sourceObjective = "Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Hey!", completion = "My screwdriver... you found my screwdriver! I'd been wondering where that thing got lost.\n\nHmm, you found it inside one of their robots, you say? That gives me an idea....", sourceObjectiveStatus = "unverified-source-field" }
quests[11730] = { id = 11730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master and Servant", description = "The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!\n\nHead back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway.\n\nI'm pretty sure it won't work on the mechagnomes, so don't even bother with them.\n\nOh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!", sourceObjective = "Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip.\n\nMake sure to loot the dead robot before you reprogram it.", progress = "How many robots have you managed to reprogram?", completion = "Woo hoo! And you brought back the screwdriver intact, too!\n\nReprogramming those robots is going to turn out to be a huge advantage in our favor in the fight against Gearmaster Mechazod. I think you've earned a little something for that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", sourceObjective = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", sourceObjectiveStatus = "unverified-source-field" }
quests[11732] = { id = 11732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Arathi Highlands bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11733] = { id = 11733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traversing the Rift", description = "I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you.\n\nThe time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept.\n\nBefore hearing the tale, you shall be shown firsthand what we face.\n\nPut your affairs in order, {class}....", sourceObjective = "Surristrasz wants you to travel to Coldarra. Once there, you are to speak with Archmage Berinand.", completion = "Welcome to Coldarra, {class}.\n\nUnder the Transitus Shield we lie hidden just a stone's throw from the Nexus, fortress of the great aspect Malygos and his blue dragonflight.\n\nDo make yourself comfortable.", sourceObjectiveStatus = "unverified-source-field" }
quests[11734] = { id = 11734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Ashenvale bonfire!", sourceObjectiveStatus = "unverified-source-field" }
