quests[11787] = { id = 11787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Zangarmarsh bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11788] = { id = 11788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lefty Loosey, Righty Tighty", description = "Okay, I think we're ready for the penultimate assault... before you can bring down Mechazod, you're going to have to dismantle his lieutenants first!\n\nYou'll find Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point and South Point stations, respectively.\n\nTo get them to show up, just turn the valves at the stations to mess up whatever they're trying to do out there. You can't miss the places, they all have spinning lights.", sourceObjective = "Dismantle Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Jinky Wingnut at Fizzcrank Airstrip.", progress = "Are Gearmaster Mechazod's lieutenants dealt with?", completion = "Wow, you survived!\n\nI guess all that's left to do now is to deal with Gearmaster Mechazod.", sourceObjectiveStatus = "unverified-source-field" }
quests[11789] = { id = 11789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soldier in Need", description = "You there!  Please, I need your help.  This soldier will succumb to the cryptfiends' venom unless we act immediately.\n\nI've managed to slow down the poison, but without a suitable supply of antidote I cannot counteract it.\n\nI was promised a new shipment of anti-venom in the Stormbreaker's most recent trip from the south.  Go inside its hold and search for a chest of first aid supplies.\n\nHurry, {class}!  We can't afford to lose any more men unnecessarily.", sourceObjective = "Medic Hawthorn, outside of Valiance Keep, wants you to go inside the Stormbreaker's hold and retrieve Hawthorn's Anti-Venom from a crate of First Aid Supplies.", progress = "The anti-venom... do you have it?", completion = "I thank you, {name}.  This man's recovery will be slow, but we won't lose him.\n\nWhat do you say?  You found cultists inside the Stormbreaker?  You'd best notify someone... and bring some evidence.", sourceObjectiveStatus = "unverified-source-field" }
quests[11790] = { id = 11790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", sourceObjective = "Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep.", completion = "Cultists?  Below deck?  I ought to have my whole crew flogged!\n\nListen... why don't we have Admiral Cantlebree take care of this... situation?", sourceObjectiveStatus = "unverified-source-field" }
quests[11791] = { id = 11791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notify Arlos", description = "We must notify General Arlos at once.  I've known the captain for a long time and, believe me, he is one of the more careful ones.\n\nWho knows how many cultists have been smuggled into our settlements in Northrend in other ships?  This could be disastrous.", sourceObjective = "Speak to General Arlos inside the Inner Hold at Valiance Keep.", completion = "Thank you for your concern, {name}.  We were made aware of the situation not too long ago.\n\nCounselor Talbot assures me that this was an isolated incident and not a cause for military concern.\n\nOur civilian authorities will make sure everyone involved is properly prosecuted.", sourceObjectiveStatus = "unverified-source-field" }
quests[11792] = { id = 11792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies of the Light", description = "Not so fast there.  I don't know about you, {class}, but I was hardly convinced by the general's words.  They rung unsure... as if they were not his own.\n\nSomething's amiss here.  All of our efforts to collaborate have been blocked and delayed.  It is time we took a more independent approach.\n\nIf we're to learn more about the cultists inside the keep... perhaps we should investigate those outside.\n\nIntelligence reports a small group of them aiding the Scourge north of here.  See if they carry any clues.", sourceObjective = "Harbinger Vurenn wants you to fight the Cultist Necrolytes near Farshire to the north of Valiance Keep and retrieve the Cultist Communique from them.", progress = "You're back, {name}.", completion = "Be discreet, {name}.  We cannot look at this evidence in front of prying eyes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11793] = { id = 11793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Investigation", description = "I'm afraid this is a matter I must delegate to one of my operatives... someone who can work in secret.  Keep the evidence with you and take it to Vindicator Yaala inside the inn.\n\nTell her I sent you and speak of this matter to no one else.  We do not know who might be working for the cult.", sourceObjective = "Bring the Cultist Communique to Vindicator Yaala inside the inn in Valiance Keep.", progress = "Harbinger Vurenn sent you?", completion = "Speak quickly, {class}.  What information do you have on the cult?", sourceObjectiveStatus = "unverified-source-field" }
quests[11794] = { id = 11794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt is On", description = "I've made it my business to learn as much as possible about the vile death cult, including their secret language.\n\nVurenn was right.  The cultists mention disguised operatives in various locations in Valiance Keep: the lower docks, the jail inside the inner hold and in the inn's kitchen.\n\nTake this oculus.  Use it at those three locations - anyone that has recently used the cult's necromancy will be enshrouded by a dark aura.  Take care of the cultists before something nefarious happens.", sourceObjective = "Vindicator Yaala wants you to use the Oculus of the Exorcist in three different locations in Valiance Keep to uncover and defeat Cult of the Damned members.", progress = "Have you accomplished the task I asked of you, {name}?", completion = "You've done well, {name}.  However, I can't shake the feeling that this is not the last we've seen of these death cultists.\n\nDarkness has a way of hiding even in plain sight.", sourceObjectiveStatus = "unverified-source-field" }
quests[11795] = { id = 11795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Protocol: Section 8.2, Paragraph C", description = "Injured or not, as squadron commander, I'm responsible for locating and returning the insignia of all fallen pilots under my command. In all the years I've flown with Fizzcrank, we've never failed to return the signet of a pilot.\n\nMy injuries make it dangerous for me to stray far from the safety of the wreckage, but perhaps you would be willing to help me recover the insignia? In the meantime, I'll make preparations to carry out my final duty as squadron commander.", sourceObjective = "Recover 6 Fizzcrank Pilot Insignia from the bodies of Fizzcrank Recon Pilots and return them to Iggy \"Tailspin\" Cogtoggle in the Scalding Pools.", progress = "Did you get those insignia?", completion = "Thank you once again, {name}. With your help, I may yet be able to complete this mission, disastrous as it's been, and return to Fizzcrank to make my report and properly honor the dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11796] = { id = 11796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Protocol: Section 8.2, Paragraph D", description = "There's only one more thing left to do before I can finally return to the airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires me to scuttle as much of the wreckage as possible, in order to prevent our technology from falling into enemy hands.\n\nI'll give you my torch if you agree to help me complete this last duty. I don't want to think about what the Horde's goblin allies will do if these machines fall into their hands.", sourceObjective = "Iggy \"Tailspin\" Cogtoggle wants you to scuttle the Eastern Wreck, a Southern Wreck, and a Northwestern Wreck.", progress = "Have you scuttled the wreckage yet?", completion = "Once again, you have my thanks, {name}. Without you, I would not have been able to recover anything useful from this disaster.", sourceObjectiveStatus = "unverified-source-field" }
quests[11797] = { id = 11797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Siege", description = "Well, well, well.  It's good to see Arlos bring out the big guns.\n\nDon't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us.  I'm not sure how much longer we can hold out against these undead Nerubians.\n\nWhat do you say you get out there and kill me some creepers?  Show these boys how it's done.", sourceObjective = "Sergeant Hammerhill wants you to kill 6 Crypt Crawlers in the Sands of Nasam outside of Valiance Keep.", progress = "You're back.  Hopefully you've put a dent in the enemy's numbers.", completion = "Nice job, {name}.  Show the lads how it's done.  The only good creeper's a dead creeper!", sourceObjectiveStatus = "unverified-source-field" }
quests[11798] = { id = 11798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gearmaster", description = "Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called 'Curse of the Flesh', but what he's really making are robotic slaves!\n\n{name}, we're pretty certain that he's still at the pumping station out in the middle of the pools to the east.\n\nThe last we saw of him, he was in the command hut up top. Go up there and research his stuff.\n\nYou must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!", sourceObjective = "Research the Gearmaster's Manual and return Mechazod's Head to Fizzcrank Fullthrottle.", progress = "Jinky told me to expect you.  Is it done?", completion = "<The old gnome breathes a heavy sigh of relief.>\n\nIt is done then... you have saved us! If you hadn't stopped him here, then who knows how far his madness would have spread?\n\nWith the threats from the blue dragons and the Nexus War, not to mention the Lich King, the last thing we need is a mad creation of the Titans running loose!\n\nThank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11799] = { id = 11799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Netherstorm bonfire!", sourceObjectiveStatus = "unverified-source-field" }
