quests[11863] = { id = 11863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Zangarmarsh flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11864] = { id = 11864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission Statement", sourceObjective = "The demon has many names and each name has held special meaning at one time or another. While the details were sometimes insignificant, the end result was always the same: death.\n\nBut it is now, nearly fifty years after it all began, that the details will find the devil and lead to his downfall.\n\nThis time, we have him... There will be no escape for Nesingwary.\n\nNorthrend will be the battleground for our war. The hunter will become the hunted!", sourceObjectiveStatus = "unverified-source-field" }
quests[11865] = { id = 11865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfit for Death", description = "Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.\n\nNesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through!\n\nTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!", sourceObjective = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers.", progress = "Feel no pity for them, {race}.", completion = "You do the Earth Mother's work, {name}, but do not revel in this victory for too long. We have discovered the hiding place of the trapper leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[11866] = { id = 11866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears of Our Enemies", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", sourceObjective = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", progress = "Ears will do quite nicely...", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!", sourceObjectiveStatus = "unverified-source-field" }
quests[11867] = { id = 11867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Ear-nough...", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", sourceObjective = "Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", progress = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!", sourceObjectiveStatus = "unverified-source-field" }
quests[11868] = { id = 11868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Culler Cometh", description = "Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!\n\nFind this murderer, Karen, and end her worthless existence.\n\nPrepare yourself properly, {name}. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her!", sourceObjective = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.", progress = "Nature demands justice!", completion = "Perhaps her death will serve as an example to others that dare slay animals for sport and riches.", sourceObjectiveStatus = "unverified-source-field" }
quests[11869] = { id = 11869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Happy as a Clam", description = "To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.\n\nOf course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.\n\nGo to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!", sourceObjective = "Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers.", progress = "It is gruesome work that we do, {name}.", completion = "Now let us see how their nerve holds up when they see what became of their companions!", sourceObjectiveStatus = "unverified-source-field" }
quests[11870] = { id = 11870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Reach", description = "We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade!\n\nShe has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra.\n\nMake haste, Liandra awaits you there!", sourceObjective = "Seek out Hierophant Liandra at the Abandoned Reach.", completion = "Cenius sent you? Well you're not a moment too soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[11871] = { id = 11871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not On Our Watch", description = "Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.\n\nThis won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!", sourceObjective = "Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts.", progress = "We will give those animals a proper burial.", completion = "A job well done, {name}. Now we strike at the pirate leader!", sourceObjectiveStatus = "unverified-source-field" }
